(function(r,f){if(typeof module==='object')module.exports=f();else r.GardenRules=f()})(globalThis,()=>{const DURATION=20000;function wave(n=1){return {number:n,elapsed:0,spawnClock:1800,spawned:0,total:Math.min(3+Math.floor(n/2),13)+(n===20?2:0),done:false}}function step(s,dt,alive){const events=[];if(s.done)return events;s.elapsed+=Math.max(0,dt);s.spawnClock-=dt;while(s.spawnClock<=0&&s.spawned<s.total){events.push({type:'spawn',giant:s.number===20&&(s.spawned===0||s.spawned===7),row:s.spawned%5});s.spawned++;s.spawnClock+=Math.max(850,1800-s.number*42)}if(s.elapsed>=DURATION&&s.spawned===s.total){if(s.number<20){s.done=true;events.push({type:'next'})}else if(alive===0&&!events.some(e=>e.type==='spawn')){s.done=true;events.push({type:'victory'})}}return events}function progress(s,victory=false){return victory?1:Math.min(.999,(s.number-1+Math.min(1,s.elapsed/DURATION))/20)}function mowers(){return Array.from({length:5},(_,row)=>({row,x:-34,state:'ready'}))}function stepMowers(list,enemies,dt,width){const kills=[];for(const m of list){if(m.state==='ready'&&enemies.some(e=>e.row===m.row&&e.alive&&e.x<=8))m.state='active';if(m.state==='active'){m.x+=420*dt;for(const e of enemies)if(e.alive&&e.row===m.row&&e.x<=m.x+45){e.alive=false;kills.push(e.id)}if(m.x>width+60)m.state='spent'}}return kills}return {DURATION,wave,step,progress,mowers,stepMowers}});
